65	/// Canonicalize a JSON value by sorting its keys.
66	fn canonicalize(value: &Value) -> Value {
67	    match value {
68	        Value::Array(items) => Value::Array(items.iter().map(canonicalize).collect()),
69	        Value::Object(map) => {
70	            let mut entries: Vec<_> = map.iter().collect();
71	            entries.sort_by(|(left, _), (right, _)| left.cmp(right));
72	            let mut sorted = Map::with_capacity(map.len());
73	            for (key, child) in entries {
74	                sorted.insert(key.clone(), canonicalize(child));
75	            }
76	            Value::Object(sorted)
77	        }
78	        _ => value.clone(),
79	    }
80	}
